use deskbox_reconstructed::{model::*,fence_merge};
#[test]fn group_move_preserves_members(){let mut c=Config::default();let a=deskbox_reconstructed::state::create_fence(&mut c,"m",[20.,20.],"a","");let b=deskbox_reconstructed::state::create_fence(&mut c,"m",[400.,20.],"b","");let id=fence_merge::group(&mut c,&a,&b).unwrap();let old=c.fences.clone();fence_merge::move_group(&mut c,&id,[600.,300.]).unwrap();assert_eq!(serde_json::to_value(&old).unwrap(),serde_json::to_value(&c.fences).unwrap());assert_eq!(fence_merge::geometry(&c,&c.fences[0])[0],600.);assert!(fence_merge::move_group(&mut c,&id,[f64::NAN,0.]).is_err());}
